gVC(){return"\u0928\u094b\u091f\u093f\u092b\u093c\u093f\u0915\u0947\u0936\u0928 \u0910\u0915\u094d\u0938\u0947\u0938 \u0928\u0939\u0940\u0902 \u0926\u093f\u092f\u093e \u0917\u092f\u093e"},
gVB(){return"\u0907\u0938\u0915\u0947 \u092c\u093f\u0928\u093e \u092d\u0940 \u0928\u0940\u091a\u0947 \u0916\u0941\u0926 \u0932\u093f\u0916\u093e \u092f\u093e \u092a\u0947\u0938\u094d\u091f \u0915\u093f\u092f\u093e \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u091c\u0935\u093e\u092c \u092c\u0928\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u093e\u092e \u0915\u0930\u0924\u093e \u0939\u0948\u0964"},
gAZ(){return"\u0905\u092a\u0928\u0940 \u0916\u0941\u0926 \u0915\u0940 AI \u0915\u0941\u0902\u091c\u0940"},
gQF(){return"AI \u0915\u093e \u0907\u0938\u094d\u0924\u0947\u092e\u093e\u0932"},
